            catch (SqlException ex)
            {
                throw new ApplicationException("Error retrieving entities from the database: " + ex.Message, ex);
            }
        }
        public List<ScenarioEvent> GetBySemanticObjectPk(long id)
        {
            List<ScenarioEvent> results = new List<ScenarioEvent>();
            try
            {
                using (var connection = new SqlConnection(_connectionString))
                using (var command = new SqlCommand(@"SELECT * FROM [model].[scenario_event]   WHERE [semantic_object_pk] = @Id", connection))
                {
                    command.Parameters.AddWithValue("@Id", id);
                    connection.Open();
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            results.Add(MapReaderToScenarioEvent(reader));
                        }
                    }
                }
                return results;
            }
            catch (SqlException ex)
            {
                throw new ApplicationException("Error retrieving entities from the database: " + ex.Message, ex);
            }
        }
        
        public ScenarioEvent MapReaderToScenarioEvent(SqlDataReader reader)
        {
            return new ScenarioEvent
            {
                CanonicalPointer = reader.GetString(reader.GetOrdinal("_canonical_pointer")),
                CanonicalPointerKey = reader.IsDBNull(reader.GetOrdinal("_canonical_pointer_key")) ? (byte[]?)null : (byte[])reader.GetValue(reader.GetOrdinal("_canonical_pointer_key")),
                OwnerDefinitionPk = reader.GetInt64(reader.GetOrdinal("_owner_definition_pk")),
                AuthorityReferenceState = reader.GetString(reader.GetOrdinal("authority_reference_state")),
                DefinitionDigest = (byte[])reader.GetValue(reader.GetOrdinal("definition_digest")),
                EventId = reader.GetString(reader.GetOrdinal("event_id")),
                ExecutionAuthorityVersionPk = reader.IsDBNull(reader.GetOrdinal("execution_authority_version_pk")) ? (long?)null : reader.GetInt64(reader.GetOrdinal("execution_authority_version_pk")),
                Name = reader.IsDBNull(reader.GetOrdinal("name")) ? (string?)null : reader.GetString(reader.GetOrdinal("name")),
                NamespacePk = reader.GetInt64(reader.GetOrdinal("namespace_pk")),
                ObjectKind = reader.GetString(reader.GetOrdinal("object_kind")),
                Responsibility = reader.GetString(reader.GetOrdinal("responsibility")),
                ScenarioVersionPk = reader.GetInt64(reader.GetOrdinal("scenario_version_pk")),
                SemanticObjectDefinitionPk = reader.GetInt64(reader.GetOrdinal("semantic_object_definition_pk")),
                SemanticObjectPk = reader.GetInt64(reader.GetOrdinal("semantic_object_pk"))
            };
        }
        
        private static readonly Dictionary<string, string> _columnNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "CanonicalPointer", "_canonical_pointer" },
            { "CanonicalPointerKey", "_canonical_pointer_key" },
            { "OwnerDefinitionPk", "_owner_definition_pk" },
            { "AuthorityReferenceState", "authority_reference_state" },
            { "DefinitionDigest", "definition_digest" },
            { "EventId", "event_id" },
            { "ExecutionAuthorityVersionPk", "execution_authority_version_pk" },
            { "Name", "name" },
            { "NamespacePk", "namespace_pk" },
            { "ObjectKind", "object_kind" },
            { "Responsibility", "responsibility" },
            { "ScenarioVersionPk", "scenario_version_pk" },
            { "SemanticObjectDefinitionPk", "semantic_object_definition_pk" },
            { "SemanticObjectPk", "semantic_object_pk" },
        };

        private static string GetColumnName(string propertyName)
        {
            return _columnNames.TryGetValue(propertyName, out var columnName) ? columnName : propertyName;
        }

        private string BuildSqlQuery(QueryDetail<ScenarioEvent> queryDetail)
        {
            var whereClauses = new List<string>();
            int index = 0;
            foreach (var criteria in queryDetail.SearchCriteria)
            {
                string columnName = GetColumnName(criteria.GetColumnName());
                if (criteria.TrimSpaces) columnName = $"TRIM({columnName})";
                string sqlOperator = QueryDetail<ScenarioEvent>.GetSqlOperator(criteria.Operator);
                whereClauses.Add($"{columnName} {sqlOperator} @{criteria.GetColumnName()}{index}");
                index++;
            }

            string whereClause = whereClauses.Any() ? "WHERE " + string.Join(" AND ", whereClauses) : string.Empty;

            var orderByClauses = new List<string>();
            foreach (var orderBy in queryDetail.OrderByList)
            {
                orderByClauses.Add($"{GetColumnName(orderBy.GetColumnName())} {QueryDetail<ScenarioEvent>.GetSqlDirection(orderBy.Direction)}");
            }

            string orderByClause = orderByClauses.Any() ? "ORDER BY " + string.Join(", ", orderByClauses) : "ORDER BY scenario_version_pk";

            return $@"SELECT e.* FROM (SELECT * FROM [model].[scenario_event]  ) e {whereClause} {orderByClause}
                  OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY";
        }
        
        public void MapValuesToScenarioEventParameters(SqlCommand command, ScenarioEvent entity)
        {
            command.Parameters.AddWithValue("@CanonicalPointer", entity.CanonicalPointer);
            command.Parameters.AddWithValue("@CanonicalPointerKey", entity.CanonicalPointerKey ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@OwnerDefinitionPk", entity.OwnerDefinitionPk);
            command.Parameters.AddWithValue("@AuthorityReferenceState", entity.AuthorityReferenceState);
            command.Parameters.AddWithValue("@DefinitionDigest", entity.DefinitionDigest);
            command.Parameters.AddWithValue("@EventId", entity.EventId);
            command.Parameters.AddWithValue("@ExecutionAuthorityVersionPk", entity.ExecutionAuthorityVersionPk ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@Name", entity.Name ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@NamespacePk", entity.NamespacePk);
            command.Parameters.AddWithValue("@ObjectKind", entity.ObjectKind);
            command.Parameters.AddWithValue("@Responsibility", entity.Responsibility);
            command.Parameters.AddWithValue("@ScenarioVersionPk", entity.ScenarioVersionPk);
            command.Parameters.AddWithValue("@SemanticObjectDefinitionPk", entity.SemanticObjectDefinitionPk);
            command.Parameters.AddWithValue("@SemanticObjectPk", entity.SemanticObjectPk);
        }
        
